package easy;public class ShortestUnsortedContinuousSubarray{public static int findUnsortedArray(int[]n){int l=n.length,r=-1;int m=Integer.MIN_VALUE,M=Integer.MAX_VALUE;for(int i=0;i<n.length;i++){if(n[i]<m||n[i]>M){r=i;break;}if(n[i]>=m)m=n[i];}for(int i=n.length-1;i>=0;i--){if(n[i]>M||n[i]<m){l=i;break;}if(n[i]<=M)M=n[i];}return r==-1?0:r-l+1;}public static void main(String[]args){System.out.println("Unsorted: "+findUnsortedArray(new int[]{2,6,4,8,10,9,15}));}}
